16	package org.springframework.samples.petclinic.service;
17	
18	import java.util.Locale;
19	
20	import org.springframework.stereotype.Component;
21	
22	/**
23	 * Derives a household's stable, shared identifier from its last name and address.
24	 *
25	 * <p>Owners belong to the same household when they share a last name and address,
26	 * compared case-insensitively and ignoring differences in surrounding or repeated
27	 * whitespace. Because the identifier is a deterministic hash of that normalized
28	 * identity, every owner in a household maps to the same value, independently and
29	 * across requests.
30	 */
31	@Component
32	public class HouseholdIdGenerator {
33	
34	    private static final String PREFIX = "HH-";
35	
36	    private static final int ID_LENGTH = 12;
37	
38	    /**
39	     * Build the shared household identifier for the household identified by the given
40	     * last name and address.
41	     *
42	     * @param lastName the household's last name
43	     * @param address  the household's address
44	     * @return the stable household identifier, e.g. {@code "HH-0A1B2C3D4E5F"}
45	     */
46	    public String generate(String lastName, String address) {
47	        String identity = normalize(lastName) + "\n" + normalize(address);
48	        return PREFIX + Sha256.hex(identity).substring(0, ID_LENGTH).toUpperCase(Locale.ROOT);
49	    }
50	
51	    /**
52	     * Normalize a household identity value for comparison: trim, collapse each run of
53	     * whitespace to a single space and lower-case, so that differences in case or
54	     * spacing do not split what is really one household.
55	     */
56	    private static String normalize(String value) {
57	        if (value == null) {
58	            return "";
59	        }
60	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
61	    }
62	}
