20	import java.security.NoSuchAlgorithmException;
21	
22	/**
23	 * Computes the SHA-256 digest of a string as lower-case hexadecimal. Shared by the
24	 * owner identity generators so the hashing is written in exactly one place.
25	 */
26	final class Sha256 {
27	
28	    private Sha256() {
29	    }
30	
