35	        try {
36	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
37	            StringBuilder hex = new StringBuilder(digest.length * 2);
38	            for (byte b : digest) {
39	                hex.append(String.format("%02x", b));
40	            }
41	            return hex.toString();
