16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "birth_date")
58	    private LocalDate birthDate;
59	
60	    @Column(name = "customer_code")
61	    private String customerCode;
62	
63	    @Column(name = "household_id")
64	    private String householdId;
65	
66	    @Column(name = "namesake_count")
67	    private Integer namesakeCount;
68	
69	    @Column(name = "bulk_signup_warning")
70	    private Boolean bulkSignupWarning;
71	
72	    @Column(name = "household_size")
73	    private Integer householdSize;
74	
75	    @Column(name = "postcode")
76	    private String postcode;
77	
78	    @Column(name = "possible_duplicate")
79	    private Boolean possibleDuplicate;
80	
81	    @Column(name = "possible_duplicate_of")
82	    private Integer possibleDuplicateOf;
83	
84	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
85	    private Set<Pet> pets;
86	
87	    public String getAddress() {
88	        return this.address;
89	    }
90	
91	    public void setAddress(String address) {
92	        this.address = address;
93	    }
94	
95	    public String getCity() {
96	        return this.city;
97	    }
98	
99	    public void setCity(String city) {
100	        this.city = city;
101	    }
102	
103	    public String getTelephone() {
104	        return this.telephone;
105	    }
106	
107	    public void setTelephone(String telephone) {
108	        this.telephone = telephone;
109	    }
110	
111	    public String getEmail() {
112	        return this.email;
113	    }
114	
115	    public void setEmail(String email) {
116	        this.email = email;
117	    }
118	
119	    public LocalDate getRegistrationDate() {
120	        return this.registrationDate;
121	    }
122	
123	    public void setRegistrationDate(LocalDate registrationDate) {
124	        this.registrationDate = registrationDate;
125	    }
126	
127	    public LocalDate getBirthDate() {
128	        return this.birthDate;
129	    }
130	
131	    public void setBirthDate(LocalDate birthDate) {
132	        this.birthDate = birthDate;
133	    }
134	
135	    public String getCustomerCode() {
136	        return this.customerCode;
137	    }
138	
139	    public void setCustomerCode(String customerCode) {
140	        this.customerCode = customerCode;
141	    }
142	
143	    public String getHouseholdId() {
144	        return this.householdId;
145	    }
146	
147	    public void setHouseholdId(String householdId) {
148	        this.householdId = householdId;
149	    }
150	
151	    public Integer getNamesakeCount() {
152	        return this.namesakeCount;
153	    }
154	
155	    public void setNamesakeCount(Integer namesakeCount) {
156	        this.namesakeCount = namesakeCount;
157	    }
158	
159	    public Boolean getBulkSignupWarning() {
160	        return this.bulkSignupWarning;
161	    }
162	
163	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
164	        this.bulkSignupWarning = bulkSignupWarning;
165	    }
166	
167	    public Integer getHouseholdSize() {
168	        return this.householdSize;
169	    }
170	
171	    public void setHouseholdSize(Integer householdSize) {
172	        this.householdSize = householdSize;
173	    }
174	
175	    public String getPostcode() {
176	        return this.postcode;
177	    }
178	
179	    public void setPostcode(String postcode) {
180	        this.postcode = postcode;
181	    }
182	
183	    /**
184	     * Whether this owner, when created, was found to be a possible (soft) duplicate of an
185	     * existing owner: not a hard duplicate, but sharing that owner's last name and postcode
186	     * while carrying a different telephone. See {@link #getPossibleDuplicateOf()}.
187	     */
188	    public Boolean getPossibleDuplicate() {
189	        return this.possibleDuplicate;
190	    }
191	
192	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
193	        this.possibleDuplicate = possibleDuplicate;
194	    }
195	
196	    /**
197	     * The id of the existing owner this owner was flagged as a possible duplicate of, or
198	     * null when it is not a possible duplicate. See {@link #getPossibleDuplicate()}.
199	     */
200	    public Integer getPossibleDuplicateOf() {
201	        return this.possibleDuplicateOf;
202	    }
203	
204	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
205	        this.possibleDuplicateOf = possibleDuplicateOf;
206	    }
207	
208	    /**
209	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY
210	     * is the last two digits of the registration date's year (e.g. {@code "NSW-1A2B3C4D-M26"}).
211	     * Derived from the owner's own fields, so it stays consistent with them.
212	     */
213	    @Transient
214	    public String getMembershipNumber() {
215	        if (this.customerCode == null || this.registrationDate == null) {
216	            return null;
217	        }
218	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
219	    }
220	
221	    /**
222	     * The owner's customer-code check digit: the single Luhn check digit (0-9) computed
223	     * over the digits of the customer code. Derived from the owner's own customer code,
224	     * so it stays consistent with it.
225	     */
226	    @Transient
227	    public Integer getCheckDigit() {
228	        if (this.customerCode == null) {
229	            return null;
230	        }
231	        return LuhnCheckDigit.of(this.customerCode);
232	    }
233	
234	    /**
235	     * The owner's membership level, a number from 1 to 3. Every owner starts at level 1;
236	     * one level is added when an email is on file and one more when the owner is unique
237	     * (namesake count of zero). The level is capped at 3, leaving level 4 reserved for
238	     * tenure. Derived from the owner's own fields, so it stays consistent with them.
239	     */
240	    @Transient
241	    public Integer getMembershipLevel() {
242	        int level = 1;
243	        boolean hasEmail = this.email != null && !this.email.isEmpty();
244	        if (hasEmail) {
245	            level++;
246	        }
247	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
248	        if (unique) {
249	            level++;
250	        }
251	        return Math.min(level, 3);
252	    }
253	
254	    /**
255	     * The owner's locality: the canonical region, taken as the region segment of the
256	     * customer code (formatted {@code '<REGION>-<HASH8>'}), so the locality stays
257	     * consistent with the owner's identity. When no customer code has been assigned yet
258	     * it falls back to resolving the region directly from the postcode and city (see
259	     * {@link RegionResolver}), the same rule the customer code itself is built from.
260	     */
261	    @Transient
262	    public String getLocality() {
263	        if (this.customerCode != null) {
264	            int separator = this.customerCode.indexOf('-');
265	            if (separator > 0) {
266	                return this.customerCode.substring(0, separator);
267	            }
268	        }
269	        return RegionResolver.regionFor(this.postcode, this.city);
270	    }
271	
272	    /**
273	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is on
274	     * file, otherwise {@code "PHONE"}. Derived from the owner's own contact details, so it
275	     * stays consistent with them.
276	     */
277	    @Transient
278	    public String getContactPreference() {
279	        boolean hasEmail = this.email != null && !this.email.isEmpty();
280	        return hasEmail ? "EMAIL" : "PHONE";
281	    }
282	
283	    /**
284	     * The owner's identity key: the single derived value used to detect duplicate owners,
285	     * formed as {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
286	     * Two owners are duplicates only when their whole identity keys are equal, so members
287	     * of one household (sharing a household id) but with different telephones stay distinct.
288	     * Derived from the owner's own fields, so it stays consistent with them.
289	     */
290	    @Transient
291	    public String getIdentityKey() {
292	        String telephonePart = this.telephone == null ? "" : this.telephone;
293	        String emailPart = this.email == null ? "" : this.email;
294	        String householdPart = this.householdId == null ? "" : this.householdId;
295	        return telephonePart + "|" + emailPart + "|" + householdPart;
296	    }
297	
298	    /**
299	     * The owner's age band relative to their registration date: {@code "MINOR"} when
300	     * under 18, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or older.
301	     * Derived from the owner's own birth and registration dates, so it stays consistent
302	     * with them; null until a birth date is on file. See {@link AgeBand}.
303	     */
304	    @Transient
305	    public String getAgeBand() {
306	        if (this.birthDate == null || this.registrationDate == null) {
307	            return null;
308	        }
309	        return AgeBand.asOf(this.birthDate, this.registrationDate).name();
310	    }
311	
312	    /**
313	     * Normalize the registration date before persisting: default it to the server's
314	     * current date when none was supplied, then roll it forward onto a business day so
315	     * every newly persisted owner is registered on a weekday.
316	     */
317	    @PrePersist
318	    void normalizeRegistrationDate() {
319	        if (this.registrationDate == null) {
320	            this.registrationDate = LocalDate.now();
321	        }
322	        this.registrationDate = BusinessDay.rollForward(this.registrationDate);
323	    }
324	
325	    protected Set<Pet> getPetsInternal() {
326	        if (this.pets == null) {
327	            this.pets = new HashSet<>();
328	        }
329	        return this.pets;
330	    }
331	
332	    protected void setPetsInternal(Set<Pet> pets) {
333	        this.pets = pets;
334	    }
335	
336	    public List<Pet> getPets() {
337	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
338	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
339	        return Collections.unmodifiableList(sortedPets);
340	    }
341	
342	    public void setPets(List<Pet> pets) {
343	        this.pets = new HashSet<>(pets);
344	    }
345	
346	    public void addPet(Pet pet) {
347	        getPetsInternal().add(pet);
348	        pet.setOwner(this);
349	    }
350	
351	    /**
352	     * Return the Pet with the given name, or null if none found for this Owner.
353	     *
354	     * @param name to test
355	     * @return true if pet name is already in use
356	     */
357	    public Pet getPet(String name) {
358	        return getPet(name, false);
359	    }
360	
361	    /**
362	     * Return the Pet with the given name, or null if none found for this Owner.
363	     *
364	     * @param name to test
365	     * @return true if pet name is already in use
366	     */
367	    public Pet getPet(String name, boolean ignoreNew) {
368	        name = name.toLowerCase();
369	        for (Pet pet : getPetsInternal()) {
370	            if (!ignoreNew || !pet.isNew()) {
371	                String compName = pet.getName();
372	                compName = compName.toLowerCase();
373	                if (compName.equals(name)) {
374	                    return pet;
375	                }
376	            }
377	        }
378	        return null;
379	    }
380	
381	    public Pet getPet(Integer petId) {
382	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
383	    }
384	
385	    @Override
386	    public String toString() {
387	        return new ToStringCreator(this)
388	
389	            .append("id", this.getId())
390	            .append("new", this.isNew())
391	            .append("lastName", this.getLastName())
392	            .append("firstName", this.getFirstName())
393	            .append("address", this.address)
394	            .append("city", this.city)
395	            .append("telephone", this.telephone)
396	            .toString();
397	    }
398	}
