36	/**
37	 * Mostly used as a facade for all Petclinic controllers
38	 * Also a placeholder for @Transactional and @Cacheable annotations
39	 *
40	 * @author Michael Isvy
41	 * @author Vitaliy Fedoriv
42	 */
43	@Service
44	public class ClinicServiceImpl implements ClinicService {
45	
46	    /**
47	     * Number of owners that must already carry a day's registration date before a
48	     * further owner registered that day is flagged with a bulk signup warning.
49	     */
50	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
51	
52	    private final PetRepository petRepository;
53	    private final VetRepository vetRepository;
54	    private final OwnerRepository ownerRepository;
55	    private final VisitRepository visitRepository;
56	    private final SpecialtyRepository specialtyRepository;
57	    private final PetTypeRepository petTypeRepository;
58	    private final CustomerCodeGenerator customerCodeGenerator;
59	    private final HouseholdIdGenerator householdIdGenerator;
60	
61	    public ClinicServiceImpl(
62	        PetRepository petRepository,
63	        VetRepository vetRepository,
64	        OwnerRepository ownerRepository,
65	        VisitRepository visitRepository,
66	        SpecialtyRepository specialtyRepository,
67	        PetTypeRepository petTypeRepository,
68	        CustomerCodeGenerator customerCodeGenerator,
69	        HouseholdIdGenerator householdIdGenerator) {
70	        this.petRepository = petRepository;
71	        this.vetRepository = vetRepository;
72	        this.ownerRepository = ownerRepository;
73	        this.visitRepository = visitRepository;
74	        this.specialtyRepository = specialtyRepository;
75	        this.petTypeRepository = petTypeRepository;
76	        this.customerCodeGenerator = customerCodeGenerator;
77	        this.householdIdGenerator = householdIdGenerator;
78	    }
79	
80	    @Override
81	    @Transactional(readOnly = true)
82	    public Collection<Pet> findAllPets() throws DataAccessException {
83	        return petRepository.findAll();
84	    }
85	
86	    @Override
87	    @Transactional(readOnly = true)
88	    public Page<Pet> findPets(Pageable pageable) throws DataAccessException {
89	        return petRepository.findAll(pageable);
90	    }
91	
92	    @Override
93	    @Transactional
94	    public void deletePet(Pet pet) throws DataAccessException {
95	        petRepository.delete(pet);
96	    }
97	
98	    @Override
99	    @Transactional(readOnly = true)
100	    public Visit findVisitById(int visitId) throws DataAccessException {
101	        return findEntityById(() -> visitRepository.findById(visitId));
102	    }
103	
104	    @Override
105	    @Transactional(readOnly = true)
106	    public Collection<Visit> findAllVisits() throws DataAccessException {
107	        return visitRepository.findAll();
108	    }
109	
110	    @Override
111	    @Transactional
112	    public void deleteVisit(Visit visit) throws DataAccessException {
113	        visitRepository.delete(visit);
114	    }
115	
116	    @Override
117	    @Transactional(readOnly = true)
118	    public Vet findVetById(int id) throws DataAccessException {
119	        return findEntityById(() -> vetRepository.findById(id));
120	    }
121	
122	    @Override
123	    @Transactional(readOnly = true)
124	    public Collection<Vet> findAllVets() throws DataAccessException {
125	        return vetRepository.findAll();
126	    }
127	
128	    @Override
129	    @Transactional
130	    public void saveVet(Vet vet) throws DataAccessException {
131	        vetRepository.save(vet);
132	    }
133	
134	    @Override
135	    @Transactional
136	    public void deleteVet(Vet vet) throws DataAccessException {
137	        vetRepository.delete(vet);
138	    }
139	
140	    @Override
141	    @Transactional(readOnly = true)
142	    public Collection<Owner> findAllOwners() throws DataAccessException {
143	        return ownerRepository.findAll();
144	    }
145	
146	    @Override
147	    @Transactional(readOnly = true)
148	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
149	        if (lastName != null) {
150	            return ownerRepository.findByLastName(lastName, pageable);
151	        }
152	        return ownerRepository.findAll(pageable);
153	    }
154	
155	    @Override
156	    @Transactional
157	    public void deleteOwner(Owner owner) throws DataAccessException {
158	        ownerRepository.delete(owner);
159	    }
160	
161	    @Override
162	    @Transactional(readOnly = true)
163	    public PetType findPetTypeById(int petTypeId) {
164	        return findEntityById(() -> petTypeRepository.findById(petTypeId));
165	    }
166	
167	    @Override
168	    @Transactional(readOnly = true)
169	    public Collection<PetType> findAllPetTypes() throws DataAccessException {
170	        return petTypeRepository.findAll();
171	    }
172	
173	    @Override
174	    @Transactional
175	    public void savePetType(PetType petType) throws DataAccessException {
176	        petTypeRepository.save(petType);
177	    }
178	
179	    @Override
180	    @Transactional
181	    public void deletePetType(PetType petType) throws DataAccessException {
182	        petTypeRepository.delete(petType);
183	    }
184	
185	    @Override
186	    @Transactional(readOnly = true)
187	    public Specialty findSpecialtyById(int specialtyId) {
188	        return findEntityById(() -> specialtyRepository.findById(specialtyId));
189	    }
190	
191	    @Override
192	    @Transactional(readOnly = true)
193	    public Collection<Specialty> findAllSpecialties() throws DataAccessException {
194	        return specialtyRepository.findAll();
195	    }
