197	    @Override
198	    @Transactional
199	    public void saveSpecialty(Specialty specialty) throws DataAccessException {
200	        specialtyRepository.save(specialty);
201	    }
202	
203	    @Override
204	    @Transactional
205	    public void deleteSpecialty(Specialty specialty) throws DataAccessException {
206	        specialtyRepository.delete(specialty);
207	    }
