209	    @Override
210	    @Transactional(readOnly = true)
211	    public Collection<PetType> findPetTypes() throws DataAccessException {
212	        return petRepository.findPetTypes();
213	    }
214	
215	    @Override
216	    @Transactional(readOnly = true)
217	    public Owner findOwnerById(int id) throws DataAccessException {
218	        return findEntityById(() -> ownerRepository.findById(id));
219	    }
