227	    @Override
228	    @Transactional
229	    public void savePet(Pet pet) throws DataAccessException {
230	        pet.setType(findPetTypeById(pet.getType().getId()));
231	        petRepository.save(pet);
232	    }
233	
234	    @Override
235	    @Transactional
236	    public void saveVisit(Visit visit) throws DataAccessException {
237	        visitRepository.save(visit);
238	
239	    }
240	
241	    @Override
242	    @Transactional(readOnly = true)
243	    public Collection<Vet> findVets() throws DataAccessException {
244	        return vetRepository.findAll();
245	    }
246	
247	    @Override
248	    @Transactional
249	    public void saveOwner(Owner owner) throws DataAccessException {
250	        if (owner.isNew()) {
251	            if (owner.getCustomerCode() == null) {
252	                owner.setCustomerCode(customerCodeGenerator.generate(
253	                    RegionResolver.regionFor(owner.getPostcode(), owner.getCity()),
254	                    owner.getTelephone(), owner.getLastName()));
255	            }
256	            owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
257	            owner.setBulkSignupWarning(
258	                ownerRepository.countByRegistrationDate(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
259	            owner.setHouseholdSize(householdSizeIncluding(owner));
260	            Optional<Owner> possibleDuplicate = findPossibleDuplicate(owner);
261	            owner.setPossibleDuplicate(possibleDuplicate.isPresent());
262	            owner.setPossibleDuplicateOf(possibleDuplicate.map(Owner::getId).orElse(null));
263	        }
264	        ownerRepository.save(owner);
265	
266	    }
267	
268	    /**
269	     * Size of the household this new owner will belong to once persisted: the owners
270	     * already sharing its household id, plus the owner itself. An owner with no shared
271	     * household id stands alone, so its household size is one.
272	     */
273	    private int householdSizeIncluding(Owner owner) {
274	        if (owner.getHouseholdId() == null) {
275	            return 1;
276	        }
277	        return (int) ownerRepository.countByHouseholdId(owner.getHouseholdId()) + 1;
278	    }
279	
280	    /**
281	     * Count the existing owners that already share the given first and last name,
282	     * compared case-insensitively. Used to stamp a new owner's namesake count at
283	     * registration, before it is itself persisted.
284	     */
285	    private int countNamesakes(String firstName, String lastName) {
286	        return (int) ownerRepository.findByLastNameIgnoreCase(lastName).stream()
287	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName))
288	            .count();
289	    }
290	
291	    /**
292	     * Find the existing owner, if any, that this new owner is a possible (soft) duplicate
293	     * of: one that shares its last name (case-insensitively) and postcode but carries a
294	     * different telephone, so it is not a hard duplicate. When several match, the earliest
295	     * (lowest id) is chosen. An owner with no postcode can share none, so never matches.
296	     */
297	    private Optional<Owner> findPossibleDuplicate(Owner owner) {
298	        if (owner.getPostcode() == null) {
299	            return Optional.empty();
300	        }
301	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
302	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
303	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
304	            .min(Comparator.comparing(Owner::getId));
305	    }
306	
307	    @Override
308	    @Transactional(readOnly = true)
309	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
310	        return ownerRepository.findByLastName(lastName);
311	    }
312	
313	    @Override
314	    @Transactional(readOnly = true)
315	    public boolean existsOwnerByIdentityKey(String identityKey) throws DataAccessException {
316	        return ownerRepository.findAll().stream()
317	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
318	    }
319	
320	    @Override
321	    @Transactional(readOnly = true)
322	    public long countOwnersByCity(String city) throws DataAccessException {
323	        return ownerRepository.countByCity(city);
324	    }
325	
326	    @Override
327	    @Transactional(readOnly = true)
328	    public long countOwnersByRegistrationDate(LocalDate registrationDate) throws DataAccessException {
329	        return ownerRepository.countByRegistrationDate(registrationDate);
330	    }
331	
332	    @Override
333	    @Transactional
334	    public String shareHousehold(Owner owner) throws DataAccessException {
335	        String householdId = householdIdGenerator.generate(owner.getLastName(), owner.getAddress());
336	        // Backfill the existing members so the whole household carries one shared id.
337	        householdMembers(owner.getLastName(), owner.getAddress()).stream()
338	            .filter(member -> !householdId.equals(member.getHouseholdId()))
339	            .forEach(member -> {
340	                member.setHouseholdId(householdId);
341	                ownerRepository.save(member);
342	            });
343	        owner.setHouseholdId(householdId);
344	        return householdId;
345	    }
346	
347	    /**
348	     * Return the existing owners that already occupy the household identified by the
349	     * given last name and address, i.e. that map to the same shared household id.
350	     */
351	    private List<Owner> householdMembers(String lastName, String address) {
352	        String householdId = householdIdGenerator.generate(lastName, address);
353	        return ownerRepository.findByLastNameIgnoreCase(lastName).stream()
354	            .filter(owner -> householdId.equals(
355	                householdIdGenerator.generate(owner.getLastName(), owner.getAddress())))
356	            .toList();
357	    }
358	
359	    @Override
360	    @Transactional(readOnly = true)
361	    public Collection<Visit> findVisitsByPetId(int petId) {
362	        return visitRepository.findByPetId(petId);
363	    }
364	
365	    @Override
366	    @Transactional(readOnly = true)
367	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
368	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
369	    }
370	
371	    private <T> T findEntityById(Supplier<T> supplier) {
372	        try {
373	            return supplier.get();
374	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
375	            // Just ignore not found exceptions for Jdbc/Jpa realization
376	            return null;
377	        }
378	    }
379	
380	}
